//! Typed column handles generated by `#[derive(EntityType)]`.
//!
//! `Entity::field` is a `Field<Entity, RustType>` carrying the physical column
//! name; `order_by_field` / `then_by_field` accept it so a typo or a renamed
//! field fails to compile instead of producing a runtime SQL error.

use rust_ef::prelude::*;
use rust_ef::query::QueryBuilder;

#[derive(Debug, Clone, EntityType)]
#[table("field_handle_items")]
struct FieldItem {
    #[primary_key]
    id: i64,
    #[column("legacy_name")]
    name: String,
    created_at: i64,
    amount: Option<i64>,
}

#[test]
fn field_constants_carry_the_physical_column_name() {
    assert_eq!(FieldItem::id.column(), "id");
    assert_eq!(FieldItem::name.column(), "legacy_name");
    assert_eq!(FieldItem::created_at.column(), "created_at");
    assert_eq!(FieldItem::amount.column(), "amount");
    assert_eq!(FieldItem::created_at.name(), "created_at");
}

#[test]
fn order_by_field_emits_the_same_order_by_as_the_string_entry() {
    let typed = QueryBuilder::<FieldItem>::new("field_handle_items")
        .order_by_field(FieldItem::created_at)
        .then_by_field_desc(FieldItem::id)
        .to_sql();
    let strings = QueryBuilder::<FieldItem>::new("field_handle_items")
        .order_by(FieldItem::COLUMN_CREATED_AT)
        .order_by_desc(FieldItem::COLUMN_ID)
        .to_sql();
    assert_eq!(typed, strings);
    assert!(
        typed.contains("ORDER BY created_at ASC, id DESC"),
        "{typed}"
    );
}

#[test]
fn field_handles_are_copy_and_belong_to_their_entity_type() {
    // The compile-time link is the `Field<Entity, V>` type; this function would
    // not accept another entity's handle.
    fn asc<V>(
        query: QueryBuilder<FieldItem>,
        field: rust_ef::query::Field<FieldItem, V>,
    ) -> QueryBuilder<FieldItem> {
        query.order_by_field(field)
    }
    let handle = FieldItem::amount;
    let _ = handle;
    let _ = asc(QueryBuilder::<FieldItem>::new("field_handle_items"), handle);
}
